```{.r .cell-code}
read_features <- function(modality) {
  read.csv(file.path("..", "data", paste0(modality, ".csv"))) |>
    as_tibble()
}

id_cols <- c("participant", "source", "ptsd", "demo_age", "demo_sex", "demo_nonwhite", "task")

df_features <-
  read_features("verbal") |>
  full_join(read_features("vocal"), by = id_cols) |>
  full_join(read_features("visual"), by = id_cols) |>
  mutate(
    group = factor(ptsd, levels = c(1, 0), labels = c("PTSD", "Control")),
    task = factor(task, levels = c("Account", "Impact"))
  )

# Feature labels, display precision, and modality, in table order
spec <- tribble(
  ~var,          ~label,                                  ~digits, ~modality,
  "WC",          "Total Word Count",                      0,       "Verbal",
  "i",           "1st Person Singular Pronouns (%)",      2,       "Verbal",
  "we",          "1st Person Plural Pronouns (%)",        2,       "Verbal",
  "emo_neg",     "Negative Emotion Words (%)",            2,       "Verbal",
  "emo_pos",     "Positive Emotion Words (%)",            2,       "Verbal",
  "allnone",     "All-or-None Words (%)",                 2,       "Verbal",
  "cogproc",     "Cognitive Process Words (%)",           2,       "Verbal",
  "Perception",  "Perception Words (%)",                  2,       "Verbal",
  "sentiment",   "Sentiment",                             2,       "Verbal",
  "SD_Loudness", "SD Loudness",                           2,       "Vocal",
  "SD_Pitch",    "SD Pitch (Hz)",                         1,       "Vocal",
  "PSR",         "Pseudo-Syllable Rate (per s)",          2,       "Vocal",
  "M_Voiced",    "Mean Voiced Regions (s)",               3,       "Vocal",
  "M_Unvoiced",  "Mean Unvoiced Regions (s)",             3,       "Vocal",
  "SD_Voiced",   "SD Voiced Regions (s)",                 3,       "Vocal",
  "SD_Unvoiced", "SD Unvoiced Regions (s)",               3,       "Vocal",
  "CPPS",        "CPPS (dB)",                             2,       "Vocal",
  "H1H2",        "H1-H2 (dB)",                            2,       "Vocal",
  "AU04",        "AU4 Brow Lowerer",                      2,       "Visual",
  "AU12",        "AU12 Lip Corner Puller",                2,       "Visual",
  "AU15",        "AU15 Lip Corner Depressor",             2,       "Visual",
